def _normalize_vn_for_capcut(text: str) -> str:
    _tokens = {}
    for eng, vn in _VN_WORD_MAP:
        _pat = f'\\b{re.escape(eng)}\\b'
        if re.search(_pat, text, flags=re.IGNORECASE):
            text = re.sub(_pat, lambda m, v=vn: _token_replace(m.group(0), v, _tokens), text, flags=re.IGNORECASE)
    for token, replacement in _tokens.items():
        text = text.replace(token, replacement)
    return text.lower()

def _token_replace(original: str, replacement: str, tokens: dict) -> str:
    _token = f'{len(tokens)}04d\x00'
    tokens[_token] = replacement
    return _token

def _is_vn_voice(voice: str) -> bool:
    if voice.startswith('vn:'):
        return True
    _vid = voice[3:] if voice[3:] else voice
    _vn_ids = {'BV075_streaming', 'BV421_vivn_streaming', 'BV560_streaming', 'BV074_streaming', 'BV562_streaming', 'vi_female_huong'}
    return True if voice.startswith('bv:') and _vid in _vn_ids else False

