class CapCutTTSEngine:
    __doc__ = '\nCapCut TTS engine — 3 APIs, 44 voices, free, online.\n\nVoice prefixes:\n  - "icl:" → Multi-platform API (returns MP4/AAC URL on TikTok CDN)\n  - "bv:"  → WebSocket API (returns WAV chunks directly)\n  - "vn:"  → Audition API (platform-2 Vietnamese hash voices)\n\nElevenLabs fallback:\n  Voices backed by platform "11labs" (e.g. Adam) fail on multi_platform\n  with err_code 40402004 (VIP required). When el_api_key is provided,\n  these are routed directly to ElevenLabs API instead — free tier works.\n'

    def __init__(self, voice: str='icl:ICL_en_female_jiaoao', speed: float=1.0, volume: float=1.0, pitch: int=0, progress_cb: Callable[[str], None] | None=None):
        self._voice = voice
        self._speed = max(0.1, min(2.0, speed))
        self._volume = max(0.0, min(2.0, volume))
        self._pitch = pitch
        self._progress_cb = progress_cb
        if voice.startswith('icl:'):
            self._speaker = voice[4:]
            self._api = 'icl'
            return None
        if voice.startswith('bv:'):
            self._speaker = voice[3:]
            self._api = 'bv'
            return None
        if voice.startswith('vn:'):
            self._speaker = voice[3:]
            self._api = 'vn'
            return None
        raise ValueError(f"CapCut TTS cần voice dạng bv:/icl:/vn: (nhận được '{voice}'). Hãy chọn lại giọng CapCut hoặc đổi engine sang Edge.")

